{
  "name": "bt_acl_conn_lookup_or_alloc",
  "confidence": "medium",
  "docstring": "Finds an existing Bluetooth ACL connection entry matching the supplied descriptor or allocates and initializes a new one from the free list, returning the connection index through the output argument.",
  "subsystem": "bt",
  "var_renames": {
    "a1": "conn_desc",
    "a2": "conn_idx",
    "v2": "conn_table",
    "v5": "conn_entry",
    "i": "table_idx",
    "v7": "alloc_entry",
    "v8": "new_conn_idx",
    "v13": "conn_entry_ptr",
    "v14": "bt_env_ptr",
    "v16": "active_conn_ptr"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "connection descriptor byte 0"
    },
    {
      "offset": 5,
      "meaning": "connection descriptor byte 1 or sequence field"
    },
    {
      "offset": 6,
      "meaning": "connection descriptor bytes 2-3"
    },
    {
      "offset": 8,
      "meaning": "connection descriptor bytes 4-5"
    },
    {
      "offset": 10,
      "meaning": "connection descriptor bytes 6-7"
    },
    {
      "offset": 12,
      "meaning": "connection descriptor tail bytes"
    },
    {
      "offset": 24,
      "meaning": "connection index/state, 0xFF marks invalid/free"
    }
  ]
}
